s=SRC.read_text()

def one(old,new,label):
    global s
    n=s.count(old)
    if n!=1: raise SystemExit(f'{label}: expected 1 occurrence, found {n}')
    s=s.replace(old,new,1)

def span(start,end,new,label):
    global s
    a=s.find(start); b=s.find(end,a+len(start))
    if a<0 or b<0: raise SystemExit(f'{label}: marker missing')
    s=s[:a]+new+s[b:]

s=s.replace('Turn 21','Turn 22').replace('TURN 21','TURN 22').replace('TURN21_','TURN22_')
