newnow='''function openEnv22(){S.level=1;S.index=null;S.componentsExpanded=false;S.nowVisible=[];S.nowActive=null;S.nowFocus=null;S.nowRepresentation=null;$('info').classList.add('hidden');$('nowTip').style.display='none';renderV1()}\nasync function collapseIndex22(){if(S.level!==2)return;S.componentsExpanded=false;S.nowVisible=[];S.nowActive=S.index;S.nowFocus=S.index;S.nowRepresentation=null;$('info').classList.add('hidden');$('nowTip').style.display='none';await renderV2()}\nasync function expandIndex22(){if(S.level!==2)return;S.componentsExpanded=true;S.nowVisible=S.def.indices[S.index].components.map(x=>x.id);S.nowActive=S.index;S.nowFocus=S.index;S.nowRepresentation=null;$('info').classList.add('hidden');$('nowTip').style.display='none';await renderV2()}\nfunction renderV1(){S.level=1;S.index=null;S.componentsExpanded=false;S.nowVisible=[];S.nowActive=null;S.nowFocus=null;$('v1btn').classList.add('hidden');$('nowTitle').textContent='ENV';renderCrumb();let w=windowFor(),colors=chartColors(IDX),sets=IDX.map(k=>{let x=S.derived.indices[k].horizons[S.h];return{id:k,label:AB[k],full:S.def.indices[k].name,unit:'Index',color:colors[k],renderType:'line',a:(x.curve||[]).map(p=>({t:+p.t,v:+p.v,idx:+p.v,raw:+p.v,sourceT:+p.t}))}});legend(sets);wireLegend19($('legend'),id=>openV2(id),'now');$('range').textContent=`${w.startLabel} → ${w.endLabel}`;setNowFooter(w,'indexed',1,true);captureNowState(sets,w,'indexed');draw('now',sets,w,'indexed')}\nasync function openV2(k){S.level=2;S.index=k;S.componentsExpanded=true;S.nowVisible=S.def.indices[k].components.map(x=>x.id);S.nowActive=k;S.nowFocus=k;S.nowRepresentation=null;S.priorV2=null;$('info').classList.add('hidden');$('nowTip').style.display='none';await renderV2()}\nasync function nowSeriesSet22(id,w,colors,mode,plan){if(IDX.includes(id)){let rec=S.derived.indices[id]?.horizons?.[S.h],a=(rec?.curve||[]).filter(p=>+p.t>=w.start&&+p.t<=w.end).map(p=>({t:+p.t,v:+p.v,idx:+p.v,raw:+p.v,sourceT:+p.t}));return{id,label:AB[id],full:S.def.indices[id]?.name||AB[id],unit:'Index',color:colors[id],renderType:'line',axis:mode==='dual'?(plan.map[id]||0):0,axisLabel:'Index',a}}let src=await getSeries(id),a=mode==='indexed'?indexed(src,w,1):nativeIndexed(src,w);return{id,label:displayLabel(id),full:name(id),unit:unit(id),color:colors[id],renderType:'line',axis:mode==='dual'?(plan.map[id]||0):0,axisLabel:unitKind(id)==='percent'?'Percent':unitKind(id)==='money'?'$ / USD':unit(id),a}}\nasync function renderV2(){let renderSeq=++S.v2RenderSeq,k=S.index;if(!k)return openEnv22();let w=windowFor(S.h,k),ids=[k,...S.nowVisible.filter(id=>id!==k)],plan=axisPlan(ids),families=plan.kinds.length,derivedOnly=ids.length>0&&ids.every(id=>IDX.includes(id)),canonical=derivedOnly?'indexed':plan.mode,mode=S.nowRepresentation||canonical;if(derivedOnly)mode='indexed';if(mode==='native'&&families!==1)mode=canonical;if(mode==='dual'&&families!==2)mode=canonical;if(!['native','dual','indexed'].includes(mode))mode=canonical;S.nowRepresentation=mode;let colors=chartColors(ids),sets=[];for(let id of ids){try{sets.push(await nowSeriesSet22(id,w,colors,mode,plan))}catch{sets.push({id,label:displayLabel(id),full:IDX.includes(id)?S.def.indices[id]?.name||AB[id]:name(id),unit:IDX.includes(id)?'Index':unit(id),color:colors[id],renderType:'line',axis:0,axisLabel:IDX.includes(id)?'Index':unit(id),a:[]})}}if(renderSeq!==S.v2RenderSeq)return;$('v1btn').classList.remove('hidden');$('nowTitle').textContent=AB[k];renderCrumb();$('range').textContent=`${w.startLabel} → ${w.endLabel}`;$('legend').innerHTML=sets.map(z=>`<button class="lg ${z.id===S.nowActive?'active':''} ${z.a.length?'':'empty'}" data-id="${z.id}" data-render-type="line" data-color-slot="${colorSlot(z.id)}" title="${esc(z.full)}" ${z.a.length?'':'disabled aria-disabled="true"'}>${legendSample(z)}${esc(z.label)}${z.id===k?'':`<span class="seriesX" data-rm="${z.id}" aria-label="Remove ${esc(z.label)}">×</span>`}</button>`).join('')+`<button class="btn legendAdd" id="nowAddSeries">Add</button>`;wireLegend19($('legend'),async id=>{if(!S.componentsExpanded&&id===k&&S.nowVisible.length===0){await expandIndex22();return}S.nowActive=id;S.nowFocus=id;$('nowTip').style.display='none';$('info').classList.add('hidden');await renderV2()},'now');$('legend').querySelectorAll('[data-rm]').forEach(x=>x.onclick=e=>{e.stopPropagation();let id=x.dataset.rm;S.nowVisible=S.nowVisible.filter(v=>v!==id);if(S.nowActive===id){S.nowActive=k;S.nowFocus=k}S.nowRepresentation=null;$('nowTip').style.display='none';renderV2()});$('nowAddSeries').onclick=()=>openNowPicker22();setNowFooter(w,mode,families,derivedOnly);captureNowState(sets,w,mode);draw('now',sets,w,mode)}\n'''
