newdiscovery='''function governed(){let o={};IDX.forEach(k=>(S.def.indices[k].components||[]).forEach(c=>o[c.id]=k));return o}\nfunction addGroup22(id){if(IDX.includes(id))return id;return governed()[id]||'other'}\nasync function openNowPicker22(){if(S.level!==2)return;$('nowPickerSearch').value='';$('nowPicker').classList.remove('hidden');await renderNowPicker22('')}\nasync function renderNowPicker22(q=''){let token=++S.nowPickerToken,needle=String(q||'').toLowerCase(),current=new Set([S.index,...S.nowVisible]),raw=S.catalog.series.map(x=>x.id).filter(id=>id!=='realGdp'),all=[...IDX,...raw].filter(id=>!current.has(id)&&`${displayLabel(id)} ${IDX.includes(id)?S.def.indices[id]?.name||'':name(id)}`.toLowerCase().includes(needle)),pairs=await Promise.all(all.map(async id=>[id,IDX.includes(id)?{available:true}:await seriesAvailability(id)]));if(token!==S.nowPickerToken)return;let av=Object.fromEntries(pairs),groups=[['risk','Risk'],['growth','Growth'],['macro','Macro'],['other','Other']],html='';for(let[g,title]of groups){let ids=all.filter(id=>addGroup22(id)===g);if(!ids.length)continue;html+=`<div class="pickerGroup">${title}</div>`;for(let id of ids){let ok=!!av[id]?.available,h=IDX.includes(id)?{classification:'derived'}:health(id),u=IDX.includes(id)?'Index':unit(id),cad=IDX.includes(id)?'derived':(cat(id).native_cadence||'—');html+=`<div class="row pickerRow ${ok?'':'empty'}"><div class="rowMain"><strong>${esc(displayLabel(id))} · ${esc(IDX.includes(id)?S.def.indices[id]?.name||displayLabel(id):name(id))}</strong><span class="rowMeta">${esc(u||'—')} · ${esc(cad)} · ${esc(h.classification||'unknown')} · ${ok?'available':'unavailable'} for ${S.h}</span></div><button class="btn" data-about-now="${id}">About</button><button class="btn" data-add-now="${id}" ${ok?'':'disabled'}>Add</button></div>`}}$('nowPickerList').innerHTML=html||'<div class="row">No matching series.</div>';$('nowPickerList').querySelectorAll('[data-about-now]').forEach(b=>b.onclick=e=>{e.stopPropagation();showInfo19(b.dataset.aboutNow,'now')});$('nowPickerList').querySelectorAll('[data-add-now]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(b.disabled)return;let id=b.dataset.addNow;if(id===S.index||S.nowVisible.includes(id))return;S.nowVisible.push(id);S.componentsExpanded=true;S.nowActive=id;S.nowFocus=id;S.nowRepresentation=null;$('nowPicker').classList.add('hidden');renderV2()})}\n$('nowPickerClose').onclick=()=>{S.nowPickerToken++;$('nowPicker').classList.add('hidden')};$('nowPickerSearch').oninput=e=>renderNowPicker22(e.target.value);\nasync function openAnalysis(ids,lineage,root){if(S.index){S.nowVisible=[...new Set(ids.filter(id=>id!==S.index))];S.componentsExpanded=true;S.nowActive=root||S.index;S.nowFocus=S.nowActive;S.nowRepresentation=null;$('analysisModal').classList.add('hidden');await renderV2();return}throw Error('Separate COMPONENT analysis is retired')}\n'''
